       $\mathbf{z_t} = \mathrm{LayerNorm} (f_{\mathrm{FC}}(\mathbf{z_t}))$\;
       $a_t{\sim}\pi_\psi(a_t|\mathbf{z}_t)$\;
       $o_{t+1}{\sim}p(o_{t{+}1}|a_t, \mathbf{o}_t = (o_t, o_{t{-}1}..o_{t{-}k}))$\;
